+            }
+            if (permissionType != null && binding.entry().permissionType() != permissionType) {
+                return false;
+            }
+            if (principal != null && !principal.equals(binding.entry().principal())) {
+                return false;
+            }
+            if (hostPattern != null && !hostPattern.matcher(binding.entry().host()).matches()) {
